svg.script:
var stages = [].slice.call(document.querySelectorAll(".panel-stage"));
var rewardItems = [].slice.call(document.querySelectorAll(".reward-item"));
var rewardSummary = document.querySelector(".reward-summary");
stages.forEach(function(stage, index) {
  function advance() {
    var next = stages[index + 1];
    if (!next || !next.classList.contains("panel-stage-hidden")) return;
    next.classList.remove("panel-stage-hidden");
    stage.setAttribute("aria-expanded", "true");
    if (next.id === "panel2") {
      rewardItems.forEach(function(item, itemIndex) {
        window.setTimeout(function() {
          item.classList.add("reward-item-visible");
        }, itemIndex * 1000);
      });
      window.setTimeout(function() {
        rewardSummary.classList.add("reward-summary-visible");
      }, rewardItems.length * 1000);
    }
  }
  stage.addEventListener("click", advance);
  stage.addEventListener("keydown", function(event) {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      advance();
    }
  });
});

var arenaRoot = document.documentElement;
var detailsButton = document.querySelector(".arena-details-button");
var backButton = document.querySelector(".arena-back-button");
var activityOptions = [].slice.call(document.querySelectorAll(".arena-option[data-action]"));
var rewardOptions = [].slice.call(document.querySelectorAll(".reward-option"));
var comparisonButtons = [].slice.call(document.querySelectorAll(".comparison-button"));
function activateByKeyboard(element, callback) {
  element.addEventListener("click", callback);
  element.addEventListener("keydown", function(event) {
    if (event.key === "Enter" || event.key === " ") { event.preventDefault(); callback(); }
  });
}
activateByKeyboard(detailsButton, function() { arenaRoot.classList.add("arena-details"); });
activateByKeyboard(backButton, function() { arenaRoot.classList.remove("arena-details"); });
var actionMessages = {
  predict: ["PREDICTION ACTIVE", "Your pick becomes a match signal."],
  battle: ["BATTLE ACTIVE", "Fan face-offs create AI feedback."],
  annotate: ["ANNOTATION ACTIVE", "Labels help validate sports AI."]
};
activityOptions.forEach(function(option) {
  activateByKeyboard(option, function() {
    var action = option.getAttribute("data-action");
    activityOptions.forEach(function(item) { item.setAttribute("aria-pressed", String(item === option)); });
    document.querySelector("#arena-live-overview").setAttribute("data-action", action);
    document.querySelector("#action-title").textContent = actionMessages[action][0];
    document.querySelector("#action-status").textContent = actionMessages[action][1];
    document.querySelector("#arena-live-overview").classList.add("is-playing");
    document.querySelector("#arena-data-pulse").setAttribute("opacity", "1");
    document.querySelector("#arena-data-motion").beginElement();
  });
});
var rewardNames = {tickets:"FRONT-ROW TICKETS", cash:"CASH IN $FXI", cornerman:"CORNERMAN ACCESS", gear:"SIGNED GEAR", status:"LEADERBOARD STATUS"};
rewardOptions.forEach(function(option) {
  activateByKeyboard(option, function() {
    var reward = option.getAttribute("data-reward");
    rewardOptions.forEach(function(item) { item.setAttribute("aria-pressed", String(item === option)); });
    var name = rewardNames[reward];
    document.querySelector("#reward-status").textContent = "Example path selected: Shots → $FXI → " + name + ".";
    document.querySelector("#reward-choice-label").textContent = name;
  });
});
comparisonButtons.forEach(function(button) {
  activateByKeyboard(button, function() {
    var isFx1 = button.getAttribute("data-comparison") === "fx1";
    comparisonButtons.forEach(function(item) { item.setAttribute("aria-pressed", String(item === button)); });
    document.querySelector("#comparison-typical").style.display = isFx1 ? "none" : "inline";
    document.querySelector("#comparison-fx1").style.display = isFx1 ? "inline" : "none";
  });
});
